CREATE FUNCTION public.validate_clinician_treatment_case_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.case_id IS DISTINCT FROM OLD.case_id AND (EXISTS(SELECT 1 FROM public.clinician_photos WHERE treatment_id=OLD.id) OR EXISTS(SELECT 1 FROM public.clinician_documents WHERE treatment_id=OLD.id)) THEN RAISE EXCEPTION 'Linked treatment case cannot change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER treatment_case_change BEFORE UPDATE ON public.clinician_treatments FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_treatment_case_change();
CREATE FUNCTION public.validate_clinician_comparison_case() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.case_id IS NOT NULL AND NEW.photo_a IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clinician_photos a JOIN public.clinician_photos b ON a.case_id=b.case_id WHERE a.id=NEW.photo_a AND b.id=NEW.photo_b AND a.case_id=NEW.case_id) THEN RAISE EXCEPTION 'Case comparison photos must belong to the same case'; END IF; RETURN NEW; END $$;
CREATE TRIGGER comparison_case BEFORE INSERT OR UPDATE ON public.clinician_notes FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_comparison_case();